//! 📚️ Native checkpoint edit order retains its exact original ledger keys through replay and cancellation.
use super::*;
use semio_framework_job::{StepContext,OriginalSourceBinding,OriginalTurnFailure,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
use semio_framework_value::{RetirementDemand,ValueRefusalKind,RetainedCloneStep,retained_clone::RetainedCloneClose};
use semio_framework_os_vcs::{ArtifactHistoryKey,HistoryPageStack};
use std::mem::{ManuallyDrop,size_of};
/// 🧳️ A sealed checkpoint order stays with its real original producer while replay borrows its keys.
pub struct OriginalCheckpointEditOrder{binding:Option<OriginalSourceBinding>,decoder:(u64,u64),frontier:(usize,u64,u64,[u8;32]),selection:ArtifactCheckpointSelection,keys:ManuallyDrop<Option<HistoryPageStack<ArtifactHistoryKey>>>,retirement:RetainedCloneClose,sealed:bool,closing:bool}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"checkpoint order changed its original caller, identity or Store frontier")}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
impl OriginalCheckpointEditOrder{
 pub fn capture_demands()->RetirementDemand{RetirementDemand{capacity_bytes:size_of::<Self>(),..fixed(2*size_of::<Self>())}}
 /// 🎟️ Captures the original borrowed checkpoint identifier and actual canonical edit issuer.
 pub fn admit<P,M>(store:&ArtifactStore<P,M>,id:&str,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>where P:ToValue+Send+Sync+'static,M:ToValue+FromValue+protocol::Mutation<P>+OpBinary+OpText+Send+'static{let decoder=cx.native_receiving_identity().ok_or_else(invalid)?;let binding=OriginalSourceBinding::borrow(cx);let parts=store.parts_ref();let frontier=(parts.owners.snapshot_read_leases.identity(),parts.log.envelope.vcs.edits.retained_issuance(),parts.cursor.generation,parts.cursor.content_revision);let d=Self::capture_demands();admit_original_construction(cx,output,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:0,depth:1},|_|Ok((Box::new(Self{binding:Some(binding),decoder,frontier,selection:ArtifactCheckpointSelection::new(id),keys:ManuallyDrop::new(Some(HistoryPageStack::empty())),retirement:Default::default(),sealed:false,closing:false}),receipt(d))))}
 fn validate<P,M>(&self,store:&ArtifactStore<P,M>,cx:&StepContext<'_>,frontier:bool)->Result<(),ValueError>where P:ToValue+Send+Sync+'static,M:ToValue+FromValue+protocol::Mutation<P>+OpBinary+OpText+Send+'static{let parts=store.parts_ref();if !self.binding.is_some_and(|b|b.matches(cx))||cx.native_receiving_identity()!=Some(self.decoder)||parts.owners.snapshot_read_leases.identity()!=self.frontier.0||parts.log.envelope.vcs.edits.retained_issuance()!=self.frontier.1||frontier&&(parts.cursor.generation!=self.frontier.2||parts.cursor.content_revision!=self.frontier.3){return Err(invalid())}Ok(())}
 /// 📐️ One row comparison or exact paged key birth selects the next independent quote.
 pub fn advance_demands(&self)->RetirementDemand{if self.selection.current_edit.is_some(){RetirementDemand{capacity_bytes:self.keys.as_ref().unwrap().next_push_allocation_bytes(),..fixed(size_of::<ArtifactHistoryKey>()+size_of::<ArtifactCheckpointSelection>())}}else{self.selection.next_demand()}}
 /// 🪡️ Original canonical change order determines the same edit rows irrespective of the live applied head.
 pub fn advance<P,M>(&mut self,store:&ArtifactStore<P,M>,id:&str,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>where P:ToValue+Send+Sync+'static,M:ToValue+FromValue+protocol::Mutation<P>+OpBinary+OpText+Send+'static{self.validate(store,cx,true)?;self.selection.validate(id)?;if self.closing{return Err(invalid().into())}if self.sealed{return Ok(true)}let d=self.advance_demands();let mut done=None;let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{if let Some(position)=self.selection.current_edit{let key=store.parts_ref().log.envelope.vcs.edits.key_at(position).ok_or_else(invalid)?;self.keys.as_mut().unwrap().try_push(key).map_err(|_|invalid())?;self.selection.advance_edit();Ok(((),receipt(d)))}else if self.selection.complete{self.sealed=true;Ok(((),receipt(d)))}else{let source=CheckpointSource{envelope:&store.parts_ref().log.envelope};self.selection.step(&source,id,grant).map(|p|((),p))}})?;Ok(self.sealed)}
 /// 👁️ Only a sealed original order lends its exact generation-keyed backing to native replay.
 pub fn borrow_order(&self)->Result<&HistoryPageStack<ArtifactHistoryKey>,ValueError>{if !self.sealed||self.closing{return Err(invalid())}self.keys.as_ref().ok_or_else(invalid)}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.terminal_is_empty(){return Ok(Default::default())}if !self.closing{return Ok(fixed(1))}if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.keys.is_some(){return self.retirement.next_owner_demands::<HistoryPageStack<ArtifactHistoryKey>>(true,&None,body)}Ok(fixed(size_of::<Option<OriginalSourceBinding>>()))}
 /// ♻️ Every original page returns before source coordinates and the borrowed checkpoint loan.
 pub fn close_step<P,M>(&mut self,store:&ArtifactStore<P,M>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>where P:ToValue+Send+Sync+'static,M:ToValue+FromValue+protocol::Mutation<P>+OpBinary+OpText+Send+'static{if self.terminal_is_empty(){return Ok(true)}self.validate(store,cx,false)?;let body=cx.retained_grant().maximum_copy_bytes;let d=self.close_demands(body)?;if !self.closing{close_original_retained_step(cx,d,|_|{self.closing=true;Ok(RetainedCloneStep::Progress(receipt(d)))})?;}else if !self.retirement.is_empty(){let selection=self.retirement.select(body)?;close_original_retained_step(cx,d,|g|selection.step(g))?;}else if self.keys.is_some(){close_original_retained_step(cx,d,|g|Ok(self.retirement.begin_granted(&mut self.keys,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default()))))?;}else{close_original_retained_step(cx,d,|_|{self.binding=None;Ok(RetainedCloneStep::Complete(receipt(d)))})?;}Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.keys.is_none()&&self.retirement.is_empty()}
 pub fn boxed_release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),..fixed(size_of::<Option<Box<Self>>>())}}
}
impl Drop for OriginalCheckpointEditOrder{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"checkpoint order requires original page and source closure");}}
